function renderExports(){const files=[['GOLD_LABELS_APPROVED_200Q.csv','Approved gold labels only. May contain only headers until every required label is approved.','CSV'],['GOLD_LABELS_REVIEW_QUEUE_200Q.csv','All candidate gold rows with current status.','CSV'],['TAX_EXPERT_QUESTION_SHEET.csv','Question-only form for an external tax professional; no model answers included.','CSV'],['TAX_EXPERT_REVIEW_RESPONSES.csv','All saved expert reference answers from the web form.','CSV'],['TAX_EXPERT_ANSWER_ASSESSMENTS.csv','Expert-facing answer ratings without internal system keys.','CSV'],['TAX_EXPERT_ANSWER_ASSESSMENTS_INTERNAL.csv','Administrator-only export with blind review linkage keys for scoring after review lock.','CSV'],['ANSWER_REVIEWS_1200.csv','Independent answer review assignments and submitted ratings.','CSV'],['ANSWER_FINAL_ADJUDICATION_600.csv','Final answer decisions for the 600 generated outputs.','CSV'],['RETRIEVAL_VALIDITY_REVIEW_3000.csv','Top-5 source/version/temporal review results.','CSV'],['PROMPT_STRATEGY_REVIEW_350.csv','Prompt-output expert ratings and proxy metrics.','CSV'],['METRICS_REPORT.csv','Metrics with final, progress, or pending status.','CSV'],['EVALUATION_MANIFEST.json','Run identifiers, scoring gate, and review progress.','JSON']];$('#queueProgressNumber').textContent=String(files.length);$('#queueProgressLabel').textContent='export files';$('#reviewQueueContent').innerHTML=`<div class="notice-box">Exports contain real saved experiment outputs and the current review state. Final legal accuracy remains blocked until the expert scoring gate is satisfied.</div><div class="export-list">${files.map(f=>`<div class="export-item"><div class="export-icon">${f[2]}</div><div><strong>${escapeHtml(f[0])}</strong><small>${escapeHtml(f[1])}</small></div><button class="button button-quiet button-small" data-export="${escapeHtml(f[0])}">Download</button></div>`).join('')}<div class="export-item"><div class="export-icon">ZIP</div><div><strong>Complete evaluation bundle</strong><small>All current review exports, manifest, and status note.</small></div><button class="button button-primary button-small" id="downloadBundle">Download bundle</button></div></div>`;$$('[data-export]').forEach(b=>b.addEventListener('click',()=>downloadFile(`/api/export/${encodeURIComponent(b.dataset.export)}`)));$('#downloadBundle').addEventListener('click',()=>downloadFile('/api/export/bundle.zip'));}
function downloadFile(url){const a=document.createElement('a');a.href=url;a.download='';document.body.appendChild(a);a.click();a.remove()}

async function loadDashboard(){try{const d=await api('/api/dashboard');$('#evaluationStatus').textContent=d.evaluation_status==='FINAL_ANSWER_METRICS_AVAILABLE'?'Final answer metrics available':'Pending expert adjudication';const cards=[['Gold labels approved',`${d.gold_approved}/${d.questions_total}`,'Requires independent reviews and administrator approval.',d.gold_approved===d.questions_total],['Answer reviews submitted',`${d.answer_reviews_done}/${d.answer_reviews_total}`,'Two independent reviews for each generated answer.',d.answer_reviews_done===d.answer_reviews_total],['Answers adjudicated',`${d.answer_adjudicated}/${d.answer_adjudication_total}`,'Final decision for each A/B/C answer.',d.answer_adjudicated===d.answer_adjudication_total],['Retrieval double reviews',`${d.retrieval_double_reviewed}/${d.retrieval_total}`,'Top-5 records with two independent reviews.',d.retrieval_double_reviewed===d.retrieval_total],['Retrieval adjudicated',`${d.retrieval_adjudicated}/${d.retrieval_total}`,'Final source and temporal validity decisions.',d.retrieval_adjudicated===d.retrieval_total],['Prompt reviews submitted',`${d.prompt_reviews_done}/${d.prompt_reviews_total}`,'Expert rating of 350 prompt outputs.',d.prompt_reviews_done===d.prompt_reviews_total],['Answer accuracy',d.answer_accuracy===null?'Pending':`${(100*d.answer_accuracy).toFixed(1)}%`,'Shown only after gold labels and all answer adjudications.',d.answer_accuracy!==null],['Correct-version retrieval',d.correct_version_retrieval_rate===null?'Pending':`${(100*d.correct_version_retrieval_rate).toFixed(1)}%`,'Shown only after all retrieval items are adjudicated.',d.correct_version_retrieval_rate!==null]];$('#metricsGrid').innerHTML=cards.map(c=>`<div class="metric-card ${c[3]?'':'pending'}"><div class="metric-label">${escapeHtml(c[0])}</div><div class="metric-value">${escapeHtml(c[1])}</div><div class="metric-foot">${escapeHtml(c[2])}</div></div>`).join('');const bars=[['Gold labels approved',d.gold_approved,d.questions_total],['Answers with two submitted reviews',d.answer_reviews_done,d.answer_reviews_total],['Answers adjudicated',d.answer_adjudicated,d.answer_adjudication_total],['Retrieval items with two reviews',d.retrieval_double_reviewed,d.retrieval_total],['Retrieval items adjudicated',d.retrieval_adjudicated,d.retrieval_total],['Prompt reviews',d.prompt_reviews_done,d.prompt_reviews_total]];$('#reviewProgressBars').innerHTML=bars.map(b=>{const pct=b[2]?100*b[1]/b[2]:0;return `<div class="progress-row"><div class="progress-row-label"><strong>${escapeHtml(b[0])}</strong><small>${Number(pct).toFixed(1)}% complete</small></div><div class="small-progress-track"><span style="width:${pct}%"></span></div><div class="progress-row-count">${b[1].toLocaleString()} / ${b[2].toLocaleString()}</div></div>`}).join('');$('#operationalTable').innerHTML=`<table><thead><tr><th>Measure</th><th>Conventional RAG</th><th>Basic Time-Filtered RAG</th><th>Amendment-Aware Temporal RAG</th></tr></thead><tbody><tr><td>Successful generations</td><td>200 / 200</td><td>200 / 200</td><td>200 / 200</td></tr><tr><td>Mean latency</td><td>19.00 s</td><td>19.19 s</td><td>19.14 s</td></tr><tr><td>Citation-marker presence</td><td>24.5%</td><td>25.0%</td><td>24.0%</td></tr><tr><td>Abstention rate</td><td>49.0%</td><td>49.5%</td><td>49.0%</td></tr><tr><td>Future-event leakage proxy</td><td><span class="mini-badge">2 flags</span></td><td>0 flags</td><td>0 flags</td></tr></tbody></table><p class="form-note">These operational and proxy figures are taken from the saved controlled run. They are not expert-approved legal accuracy results.</p>`;$('#statQuestions').textContent=d.questions_total.toLocaleString();$('#statAnswers').textContent=(d.generation_count||600).toLocaleString();$('#statEvidence').textContent=(d.retrieval_total||3000).toLocaleString();}catch(err){console.warn(err)}}

async function loadInitial(){try{const d=await api('/api/status');$('#statQuestions').textContent=d.questions.toLocaleString();$('#statAnswers').textContent=d.answers.toLocaleString();$('#statEvidence').textContent=d.retrieval_records.toLocaleString();if(d.live_backend_configured){$('.hero-note .note-foot').innerHTML='<span class="status-dot"></span> Live RAG backend configured'};}catch(err){console.warn(err)}await refreshMe();loadDashboard()}
loadInitial();
